import {normalizeConfig,presets,profiles,glasses,lights} from './configurator-model.mjs';

export const photoAssets=Object.freeze({mixed:'assets/configurator/mixed-real.png',clothes:'assets/configurator/clothes-real.png',shelves:'assets/configurator/shelves-real.png'});

// Photographic transparent plates provide the material detail. Geometry and all
// finish/light layers remain deterministic and respond to normalized settings.
export function realisticScene(input,{doorsOpen=false}={}){
 const c=normalizeConfig(input),p=presets[c.preset],profile=profiles[c.profile],glass=glasses[c.glass],light=lights[c.light];
 const scale=Math.min(810/c.width,570/c.height),w=c.width*scale,h=c.height*scale,x=(1000-w)/2,y=666-h,bay=w/3,lit=c.light!=='off';
 const photo=photoAssets[c.preset];
 const metal=c.profile==='bronze'?['#503b25','#b99a6e','#6e5033','#d9c09a']:c.profile==='silver'?['#60665f','#ccd0c8','#878e83','#e3e7df']:['#20221f','#6d7067','#343831','#92958a'];
 const opacity={clear:.025,smoked:.14,bronze:.15,open:0}[c.glass];
 const image=`<svg x="${x}" y="${y}" width="${w}" height="${h}" viewBox="70 52 1207 1072" preserveAspectRatio="none" overflow="hidden"><image href="${photo}" width="1341" height="1173"/></svg>`;
 let illumination='',doors='';
 for(let i=0;i<3;i++){
  const bx=x+bay*i;
  if(lit)illumination+=`<g class="real-led"><rect x="${bx+8}" y="${y+10}" width="${bay-16}" height="${h-18}" fill="url(#realWash)" style="mix-blend-mode:screen"/><path d="M${bx+14} ${y+13}v${h-26}" stroke="${light.color}" stroke-width="7" opacity=".6" filter="url(#realLedBlur)"/><path d="M${bx+14} ${y+13}v${h-26}" stroke="${light.color}" stroke-width="2.4" opacity=".9"/><path d="M${bx+14} ${y+13}v${h-26}" stroke="#fff9e6" stroke-width=".6" opacity=".9"/></g>`;
  if(c.glass!=='open'&&!doorsOpen)doors+=`<g class="real-glass"><rect x="${bx+3}" y="${y+3}" width="${bay-6}" height="${h-6}" fill="${glass.color}" opacity="${opacity}"/><rect x="${bx+5}" y="${y+5}" width="${bay-10}" height="${h-10}" fill="url(#realGlass)"/><path d="M${bx+bay*.24} ${y+7}l-${bay*.16} ${h-14}h${bay*.09}l${bay*.16} -${h-14}Z" fill="#eae6dc" opacity=".06"/><path d="M${bx+bay-10} ${y+h*.44}v${h*.15}" stroke="#171b16" stroke-width="4"/><path d="M${bx+bay-9} ${y+h*.44}v${h*.15}" stroke="url(#realMetal)" stroke-width="2"/><rect x="${bx+2}" y="${y+2}" width="${bay-4}" height="${h-4}" fill="none" stroke="url(#realMetal)" stroke-width="3"/></g>`;
 }
 const posts=[0,1,2,3].map((i)=>`<rect x="${x+i*bay-(i===3?5:0)}" y="${y}" width="5" height="${h}" fill="url(#realMetal)"/><path d="M${x+i*bay+(i===3?-1:4)} ${y+1}v${h-2}" stroke="${metal[3]}" stroke-width=".5" opacity=".65"/>`).join('');
 return `<svg class="realistic-scene" data-profile="${c.profile}" viewBox="0 0 1000 780" xmlns="http://www.w3.org/2000/svg" role="img" aria-labelledby="real-title real-desc"><title id="real-title">Гардеробная: ${p.name}</title><desc id="real-desc">Фотореалистичный концепт. ${c.width} × ${c.height} × 60 см. ${profile.name}, ${glass.name}, ${light.name}. Не технический проект и не фотография готового изделия.</desc><defs>
 <linearGradient id="realWall" x2="1" y2=".8"><stop stop-color="#b8b1a4"/><stop offset=".45" stop-color="#99968c"/><stop offset="1" stop-color="#706f66"/></linearGradient><linearGradient id="realFloor" x2="0" y2="1"><stop stop-color="#aaa697"/><stop offset="1" stop-color="#d2ccbf"/></linearGradient><linearGradient id="realMetal"><stop stop-color="${metal[0]}"/><stop offset=".23" stop-color="${metal[1]}"/><stop offset=".52" stop-color="${metal[2]}"/><stop offset="1" stop-color="${metal[3]}"/></linearGradient><linearGradient id="realGlass" x1="0" y1=".2" x2="1" y2=".4"><stop stop-color="#f5f1e4" stop-opacity=".13"/><stop offset=".24" stop-color="#f5f1e4" stop-opacity=".02"/><stop offset=".58" stop-color="#000" stop-opacity="0"/><stop offset="1" stop-color="#dddccd" stop-opacity=".07"/></linearGradient><linearGradient id="realWash"><stop stop-color="${light.color}" stop-opacity=".18"/><stop offset=".22" stop-color="${light.color}" stop-opacity=".045"/><stop offset="1" stop-color="${light.color}" stop-opacity="0"/></linearGradient><linearGradient id="realTopLight" x2="0" y2="1"><stop stop-color="#efe7d7" stop-opacity=".26"/><stop offset="1" stop-color="#efe7d7" stop-opacity="0"/></linearGradient><radialGradient id="realVignette"><stop offset=".45" stop-color="#000" stop-opacity="0"/><stop offset="1" stop-color="#24261e" stop-opacity=".2"/></radialGradient><filter id="realTexture"><feTurbulence type="fractalNoise" baseFrequency=".52" numOctaves="3" seed="7"/><feColorMatrix type="saturate" values="0"/><feComponentTransfer><feFuncA type="linear" slope=".035"/></feComponentTransfer><feBlend in="SourceGraphic" mode="soft-light"/></filter><filter id="realSoftShadow" x="-40%" y="-100%" width="180%" height="300%"><feGaussianBlur stdDeviation="18"/></filter><filter id="realContact" x="-15%" y="-100%" width="130%" height="300%"><feGaussianBlur stdDeviation="3"/></filter><filter id="realLedBlur" x="-2000%" y="-20%" width="4100%" height="140%"><feGaussianBlur stdDeviation="5"/></filter><clipPath id="realCabinetClip"><rect x="${x}" y="${y}" width="${w}" height="${h}"/></clipPath></defs>
 <rect width="1000" height="780" fill="url(#realWall)" filter="url(#realTexture)"/><path d="M0 657h1000v123H0Z" fill="url(#realFloor)" filter="url(#realTexture)"/><path d="M0 657h1000" stroke="#696c60" stroke-width="1" opacity=".2"/><path d="M0 661h1000" stroke="#ded7c9" opacity=".25"/><path d="M140 657L40 780M500 657v123M850 657l120 123" stroke="#8d8d7e" stroke-width=".6" opacity=".18"/>
 <path d="M0 0h220L530 657H0Z" fill="#e9e0ce" opacity=".1"/><path d="M30 0h3l310 657h-3Z" fill="#eae3d6" opacity=".11"/><rect x="${x-25}" y="${y-12}" width="${w+50}" height="${h+21}" rx="12" fill="#272b22" opacity=".25" filter="url(#realSoftShadow)"/><ellipse cx="${x+w/2+12}" cy="674" rx="${w*.55}" ry="20" fill="#1b2117" opacity=".34" filter="url(#realSoftShadow)"/><ellipse cx="500" cy="666" rx="${w*.49}" ry="5" fill="#1c2018" opacity=".7" filter="url(#realContact)"/>
 <g class="real-cabinet">${image}<g clip-path="url(#realCabinetClip)">${illumination}<rect x="${x}" y="${y}" width="${w}" height="${h*.28}" fill="url(#realTopLight)" style="mix-blend-mode:soft-light"/></g><g class="real-profile">${posts}<rect x="${x}" y="${y}" width="${w}" height="4" fill="url(#realMetal)"/><rect x="${x}" y="${y+h-4}" width="${w}" height="4" fill="url(#realMetal)"/></g>${doors}</g>
 <rect width="1000" height="780" fill="url(#realVignette)" pointer-events="none"/><text x="500" y="744" text-anchor="middle" fill="#5e6255" font-family="Manrope,Arial,sans-serif" font-size="10" letter-spacing="3">IKIGAI / ЛИЧНОЕ ПРОСТРАНСТВО</text></svg>`;
}
